value.contents:
/* breadcrumb — DS .crumb / NotePage breadcrumb */
.kb-crumb {
  font-family: var(--mono);
  font-size: var(--kb-text-2xs);
  letter-spacing: 0.04em;
  color: var(--faint);
  text-transform: uppercase;
}
/* crumb links keep the crumb's own color; only the hover underline says they are links */
.kb-crumb a {
  color: inherit;
  text-decoration: none;
}
.kb-crumb a:hover,
.kb-crumb a:focus-visible {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* title — Ming 34/600 */
.kb-note-title {
  font-family: var(--ming);
  font-size: var(--kb-text-h1-note);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin: 12px 0 0;
  color: var(--ink);
}

/* meta row — mono uppercase, domain-colored pill + updated */
.kb-note-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  margin-top: 14px;
  font-family: var(--mono);
  font-size: var(--kb-text-2xs);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--faint);
}
.kb-type-tag {
  border: 1px solid var(--accent);
  border-radius: 999px;
  padding: 2px 9px;
}
.kb-note-dek {
  margin: 16px 0 0;
  max-width: 64ch;
  font-family: var(--ming);
  font-size: var(--kb-text-base);
  line-height: var(--kb-lh-body);

.door__kind :global(.kb-icon) {
  font-size: 12px;
  color: var(--dc);
  opacity: 0.7;
  line-height: 1;
}
.door__intent {
  font-family: var(--mono);
  font-size: 0.75rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--dc);
}
.door__title {
  font-family: var(--ming);
  font-size: var(--kb-text-base);
  font-weight: 600;
  line-height: 1.2;
  color: var(--ink);
}

}
:global([data-theme='dark']) .kb-brand__mark {
  color: #a78bfa;
}
.kb-brand__name {
  white-space: nowrap;
}
.kb-brand__kicker {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--faint);
  font-weight: 400;
}

/* nav (screens.jsx L11–22, L30–32) */
.kb-nav {
  display: flex;
  gap: 4px;
  margin-left: 8px;
}
.kb-nav__link {
  font-family: var(--sans);
  font-size: var(--kb-text-sm);
  color: var(--mut);
  background: transparent;
  border: none;
  padding: 6px 12px;
  border-radius: var(--tsg-radius-sm);
  text-decoration: none;
  cursor: pointer;
}
.kb-nav__link.on {
  color: var(--accent);
  background: var(--accent-soft);
}

.kb-spacer {
  flex: 1;

  color: var(--ink);
}
.head {
  margin-bottom: 16px;
}
.head__kind {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  text-decoration: none;
}
.head__kind:hover {
  text-decoration: underline;
}
.head h1 {
  font-family: var(--ming);
  font-size: 1.8rem;
  font-weight: 500;
  margin: 5px 0 2px;

  border-radius: 8px;
  text-decoration: none;
  color: var(--ink);
}
.kb-ac-row.on,
.kb-ac-row:hover {
  background: var(--accent-soft);
}
.kb-ac-title {
  font-family: var(--ming);
  font-size: var(--kb-text-base);
  /* A grid item's auto minimum is its longest word, so a long title used to widen the row
     and wrap to two and three lines. Clamp it to one line instead. */
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kb-ac-domain {
  font-family: var(--mono);
  font-size: var(--kb-text-2xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  white-space: nowrap;
  /* "Generativity" is the longest label and the most common one; uncapped it ate the title. */
  max-width: 84px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.notes-lede a:hover {
  border-bottom-color: var(--accent);
}
.notes-head {
  font-family: var(--ming);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--ink);
  margin: 1.6rem 0 0.35rem;
}
.notes-sub {
  font-size: var(--kb-text-base);
  line-height: var(--kb-lh-body);
  color: var(--mut);
  margin: 0 0 0.75rem;
  max-width: 64ch;
}
.entry-list {
  list-style: none;
  margin: 0;

